    import { mapState, mapMutations } from 'vuex'
	// import theme from "@/mixins/theme";
    export default {
        name: 'sign_in',
        cname: '签到',
        configName: 'c_sign_in',
        icon: '#iconzujian-qiandao',
        type:1,// 0 基础组件 1 营销组件 2工具组件
        defaultName:'signIn', // 外面匹配名称
        props: {
            index: {
                type: null,
                default: -1
            },
            num: {
                type: null
            },
			colorStyle:{
				type: null
			}
        },
        computed: {
            ...mapState('admin/mobildConfig', ['defaultArray'])
        },
        watch: {
            pageData: {
                handler (nVal, oVal) {
                    this.setConfig(nVal)
                },
                deep: true
            },
            num: {
                handler (nVal, oVal) {
                    let data = this.$store.state.admin.mobildConfig.defaultArray[nVal]
                    this.setConfig(data)
                },
                deep: true
            },
            'defaultArray': {
                handler (nVal, oVal) {
                    let data = this.$store.state.admin.mobildConfig.defaultArray[this.num]
                    this.setConfig(data);
                },
                deep: true
            }
        },
		// mixins: [theme],
        data () {
            return {
                // 默认初始化数据禁止修改
                defaultConfig: {
					cname: '签到',
                    name: 'signIn',
                    timestamp: this.num,
					isHide:false,
					setUp: {
					  tabVal: 0
					},
					titleLeft:'展示设置',
					titleRight:'签到样式',
					titleCurrency:'通用样式',
					styleConfig:{
						title: '选择风格',
						tabVal:0,
						type:'signIn'
					},
					toneConfig:{
						title: '色调',
						tabVal: 0,
						tabList: [
							{
							  name: '跟随主题风格'
							},
						    {
						      name: '自定义'
						    }
						]
					},
					bntBgColor:{
						title: '按钮背景',
						name: 'bntBgColor',
						default: [
							{
								item: '#FF7931'
							},
							{
								item: '#E93323'
							}
						],
						color: [
							{
								item: '#FF7931'
							},
							{
								item: '#E93323'
							}
						]
					},
					bntTxtColor:{
						title: '按钮文字',
						name: 'bntTxtColor',
						default: [
							{
								item: '#FFF'
							}
						],
						color: [
							{
								item: '#FFF'
							}
						]
					},
					labelBgColor:{
						title: '标签背景',
						name: 'labelBgColor',
						default: [
							{
								item: '#FCEAE9'
							}
						],
						color: [
							{
								item: '#FCEAE9'
							}
						]
					},
					labelTxtColor:{
						title: '标签文字',
						name: 'labelBgColor',
						default: [
							{
								item: '#E93323'
							}
						],
						color: [
							{
								item: '#E93323'
							}
						]
					},
                    moduleColor: {
                        title: '组件背景',
                        name: 'moduleColor',
                        default: [
                        	{
                        		item: '#FF7931'
                        	},
                        	{
                        		item: '#E93323'
                        	}
                        ],
                        color: [
                        	{
                        		item: '#FF7931'
                        	},
                        	{
                        		item: '#E93323'
                        	}
                        ]
                    },
					moduleColor2: {
					    title: '组件背景',
					    name: 'moduleColor2',
					    default: [
					    	{
					    		item: '#FFF'
					    	},
					    	{
					    		item: '#FFF'
					    	}
					    ],
					    color: [
					    	{
					    		item: '#FFF'
					    	},
					    	{
					    		item: '#FFF'
					    	}
					    ]
					},
					bottomBgColor: {
					    title: '底部背景',
					    name: 'bgColor',
					    default: [
					    	{
					    		item: '#f5f5f5'
					    	}
					    ],
					    color: [
					    	{
					    		item: '#f5f5f5'
					    	}
					    ]
					},
					topConfig: {
					    title: '上边距',
					    val: 0,
					    min: 0
					},
					bottomConfig: {
					    title: '下边距',
					    val: 0,
					    min: 0
					},
					prConfig: {
					    title: '左右边距',
					    val: 0,
					    min: 0
					},
					mbConfig: {
					    title: '页面上间距',
					    val: 0,
					    min: 0
					},
					fillet:{
						title:'背景圆角',
						type: 0,
						list: [
						  {
						    val: "全部",
						    icon: "iconcaozuo-zhengti",
						  },
						  {
						    val: "单个",
						    icon: "iconcaozuo-bianjiao",
						  }
						],
						valName:'圆角值',
						val: 0,
						min: 0,
						valList:[
							{val:0},
							{val:0},
							{val:0},
							{val:0}
						]
					}
                },
				pageData: {},
				bottomBgColor:'',
				topConfig:'',
				bottomConfig:'',
				prConfig:0,
				styleConfig:0,
				toneConfig:0,
				bntBgColorLeft:'',
				bntBgColorRight:'',
				bntTxtColor:'',
				labelBgColor:'',
				labelTxtColor:'',
				bgColorLeft:'',
				bgColorRight:'',
				bgColorLeft2:'',
				bgColorRight2:'',
				mbConfig:0,
				bgRadius:0,
				themeColor:''
            }
        },
        mounted () {
            this.$nextTick(() => {
                this.pageData = this.$store.state.admin.mobildConfig.defaultArray[this.num]
                this.setConfig(this.pageData)
            })
        },
        methods: {
            setConfig (data) {
                if(!data) return
                if(data.mbConfig){
					this.styleConfig = data.styleConfig.tabVal;
					this.toneConfig = data.toneConfig.tabVal;
					this.bntBgColorLeft = data.bntBgColor.color[0].item;
					this.bntBgColorRight = data.bntBgColor.color[1].item;
					this.bntTxtColor = data.bntTxtColor.color[0].item;
					this.labelBgColor = data.labelBgColor.color[0].item;
					this.labelTxtColor = data.labelTxtColor.color[0].item;
					this.themeColor = `linear-gradient(90deg,${this.colorStyle.theme} 0%,${this.colorStyle.gradient} 100%)`;
					this.bgColorLeft = data.moduleColor.color[0].item;
					this.bgColorRight = data.moduleColor.color[1].item;
					this.bgColorLeft2 = data.moduleColor2.color[0].item;
					this.bgColorRight2 = data.moduleColor2.color[1].item;
					this.bottomBgColor = data.bottomBgColor.color[0].item;
					this.topConfig = data.topConfig.val;
					this.bottomConfig = data.bottomConfig.val;
					this.prConfig = data.prConfig.val;
					this.mbConfig = data.mbConfig.val;
					let fillet = data.fillet.type;
					let filletVal = data.fillet.val
					let valList = data.fillet.valList;
					this.bgRadius = fillet? valList[0].val+ 'px ' +valList[1].val + 'px ' +valList[3].val + 'px ' +valList[2].val + 'px' : filletVal +'px';
                }
            }
        }
    }
